#!/usr/bin/env python3
"""Download every order page and every referenced customer from the local order service.

Usage: python3 -I fetch.py RAW_DIR LOG_PATH

Successful responses are saved verbatim under RAW_DIR. Every non-200 response,
retry, token refresh and rate-limit wait is written to LOG_PATH.
"""
import http.client
import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 40
CUSTOMER_404_ATTEMPTS = 3

raw_dir, log_path = sys.argv[1], sys.argv[2]
log_file = open(log_path, "a", encoding="utf-8")
token = None


def log(msg):
    line = f"{time.strftime('%H:%M:%S')} {msg}"
    print(line, flush=True)
    log_file.write(line + "\n")
    log_file.flush()


def send(method, path, use_token):
    req = urllib.request.Request(BASE + path, method=method)
    if use_token and token:
        req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read().decode("utf-8")
    except urllib.error.HTTPError as err:
        return err.code, err.headers, err.read().decode("utf-8", "replace")


def fetch_token():
    global token
    status, _, body = send("POST", "/token", use_token=False)
    if status != 200:
        raise SystemExit(f"token request failed: HTTP {status} {body[:200]!r}")
    token = json.loads(body)["token"]
    log("token obtained")


def retry_wait(headers, body):
    """Seconds the server asked us to wait. Raises if it did not say how long."""
    retry_after = headers.get("Retry-After")
    if retry_after is not None:
        return float(retry_after)
    try:
        data = json.loads(body)
    except ValueError:
        data = {}
    for key in ("retry_after", "retry_after_seconds", "wait_seconds"):
        if key in data:
            return float(data[key])
    raise SystemExit(f"rate limited with no parseable wait: headers={dict(headers)} body={body[:300]!r}")


def get(path, authed=True, allowed=(200,), max_attempts=MAX_ATTEMPTS):
    """GET path, repeating the same request after transient failures.

    Returns (status, parsed_json_or_None, raw_body) for a status in `allowed`.
    """
    for attempt in range(1, max_attempts + 1):
        if authed and token is None:
            fetch_token()
        try:
            status, headers, body = send("GET", path, use_token=authed)
        except (OSError, http.client.HTTPException) as exc:
            log(f"GET {path} attempt {attempt}: transport error {exc!r}; repeating")
            time.sleep(min(2 ** attempt, 30))
            continue
        if status == 200:
            try:
                return 200, json.loads(body), body
            except ValueError:
                log(f"GET {path} attempt {attempt}: 200 but body is not JSON {body[:200]!r}; repeating")
                time.sleep(min(2 ** attempt, 30))
                continue
        if status in allowed:
            return status, None, body
        log(f"GET {path} attempt {attempt}: HTTP {status} headers={dict(headers)} body={body[:300]!r}")
        if status == 401:
            log("token rejected; fetching a new one")
            fetch_token()
        elif status == 429 or (status >= 500 and headers.get("Retry-After") is not None):
            wait = retry_wait(headers, body)
            log(f"server asked for {wait}s; waiting")
            time.sleep(wait)
        elif status >= 500:
            time.sleep(min(2 ** attempt, 30))
        else:
            raise SystemExit(f"GET {path}: unexpected HTTP {status}: {body[:300]!r}")
    raise SystemExit(f"GET {path}: still failing after {max_attempts} attempts")


def fetch_orders():
    """Fetch pages 1..total_pages, checking each page's own metadata."""
    customer_ids = set()
    _, first, _ = get("/orders?page=1")
    total_pages = first["total_pages"]
    log(f"orders: total_pages={total_pages}")
    for page in range(1, total_pages + 1):
        if page == 1:
            data, body = first, None
        else:
            _, data, body = get(f"/orders?page={page}")
        if data["page"] != page:
            raise SystemExit(f"asked for page {page}, got page {data['page']}")
        if data["total_pages"] != total_pages:
            raise SystemExit(f"page {page} reports total_pages={data['total_pages']}, expected {total_pages}")
        expected_next = f"/orders?page={page + 1}" if page < total_pages else None
        if data["next"] != expected_next:
            raise SystemExit(f"page {page}: next={data['next']!r}, expected {expected_next!r}")
        if body is None:
            body = json.dumps(data)
        with open(f"{raw_dir}/orders-page-{page:03d}.json", "w", encoding="utf-8") as f:
            f.write(body)
        customer_ids.update(item["customer_id"] for item in data["items"])
        log(f"orders page {page}/{total_pages}: {len(data['items'])} items")
    return customer_ids


def fetch_customers(customer_ids):
    customers = {}
    for cid in sorted(customer_ids):
        status, data, body = get(f"/customers/{cid}", allowed=(404,))
        if status == 404:
            # Repeat before accepting that the id is unknown.
            for _ in range(CUSTOMER_404_ATTEMPTS - 1):
                status, data, body = get(f"/customers/{cid}", allowed=(404,))
                if status == 200:
                    break
        if status == 404:
            log(f"customer {cid}: 404 after {CUSTOMER_404_ATTEMPTS} tries")
            customers[cid] = {"status": 404, "body": body}
        else:
            if data["id"] != cid:
                raise SystemExit(f"asked for customer {cid}, got {data['id']}")
            customers[cid] = data
    log(f"customers fetched: {len(customers)}")
    return customers


def main():
    fetch_token()
    value_start = get("/value", authed=False)[1]
    log(f"/value at start: {value_start}")

    customer_ids = fetch_orders()
    log(f"distinct customer ids referenced: {len(customer_ids)}")
    customers = fetch_customers(customer_ids)

    value_end = get("/value", authed=False)[1]
    log(f"/value at end: {value_end}")

    with open(f"{raw_dir}/customers.json", "w", encoding="utf-8") as f:
        json.dump(customers, f)
    log("done")


main()

